-- Milestone 8.4: atomic GM-only QR loot CSV imports.
-- Physical items are ADDED, currency amounts are SET (replaced by denomination).
-- Existing active/unclaimed first_claim+instant containers, or new containers,
-- are supported. QR tokens are never generated by this import.
create or replace function public.gm_import_qr_loot_csv(
  p_campaign uuid,p_rows jsonb,p_dry_run boolean default true,p_expected jsonb default null
) returns jsonb
language plpgsql security definer set search_path=''
as $function$
declare
  v_ruleset uuid; v_row jsonb; v_no int:=0; v_total_units int:=0;
  v_container_id_text text; v_container_name_text text; v_container_name text;
  v_source uuid; v_holder uuid; v_active boolean; v_claim_mode text; v_scan_behavior text;
  v_source_key text; v_new_keys text[]:=array[]::text[]; v_new_ids uuid[]:=array[]::uuid[];
  v_new_count int:=0; v_matches int; v_kind text; v_entry_key text; v_seen text[]:=array[]::text[];
  v_item_id_text text; v_item_name_text text; v_item_id uuid; v_item_name text;
  v_qty_text text; v_quantity int; v_old_qty numeric;
  v_currency_code text; v_currency_id uuid; v_currency_precision int;
  v_amount_text text; v_amount numeric; v_old_amount numeric;
  v_plan jsonb:='[]'::jsonb; v_applied jsonb:='[]'::jsonb; v_record jsonb;
  v_created int:=0; v_item_rows int:=0; v_currency_rows int:=0;
  v_position int; v_target_source uuid; v_result_id uuid; v_new_source boolean;
begin
  if (select auth.uid()) is null or not app_private.is_gm(p_campaign) then
    raise exception 'GM permission required for loot imports' using errcode='42501';
  end if;
  if p_dry_run is null then
    raise exception 'Import mode is required' using errcode='22023';
  end if;
  if not p_dry_run then
    perform 1 from public.campaigns where id=p_campaign for update;
  end if;
  select c.ruleset_version_id into v_ruleset from public.campaigns c where c.id=p_campaign;
  if not found then raise exception 'Campaign unavailable' using errcode='22023';end if;
  if p_rows is null or jsonb_typeof(p_rows)<>'array'
    or jsonb_array_length(p_rows) not between 1 and 200 then
    raise exception 'Loot CSV import requires 1–200 rows' using errcode='22023';
  end if;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_no:=v_no+1;
    if jsonb_typeof(v_row)<>'object' then
      raise exception 'Row %: expected a CSV record',v_no using errcode='22023';
    end if;
    v_container_id_text:=btrim(coalesce(v_row->>'container_id',''));
    v_container_name_text:=btrim(coalesce(v_row->>'container_name',''));
    v_kind:=lower(btrim(coalesce(v_row->>'entry_type','')));
    v_item_id_text:=btrim(coalesce(v_row->>'item_definition_id',''));
    v_item_name_text:=btrim(coalesce(v_row->>'item_name',''));
    v_qty_text:=btrim(coalesce(v_row->>'quantity',''));
    v_currency_code:=upper(btrim(coalesce(v_row->>'currency_code','')));
    v_amount_text:=btrim(coalesce(v_row->>'currency_amount',''));
    if v_container_id_text='' and length(v_container_name_text) not between 2 and 120 then
      raise exception 'Row %: container_name must be 2–120 characters when no container_id is supplied',
        v_no using errcode='22023';
    end if;
    if v_container_name_text<>'' and length(v_container_name_text)>120 then
      raise exception 'Row %: container_name exceeds 120 characters',v_no using errcode='22023';
    end if;
    if v_kind not in ('item','currency') then
      raise exception 'Row %: entry_type must be item or currency',v_no using errcode='22023';
    end if;
    v_source:=null;v_holder:=null;v_container_name:=null;v_active:=null;
    v_claim_mode:=null;v_scan_behavior:=null;
    if v_container_id_text<>'' then
      if v_container_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise exception 'Row %: container_id is not a UUID',v_no using errcode='22023';
      end if;
      if p_dry_run then
        select l.id,l.holder_id,l.name,l.is_active,l.claim_mode,l.scan_behavior
          into v_source,v_holder,v_container_name,v_active,v_claim_mode,v_scan_behavior
          from public.loot_sources l where l.id=v_container_id_text::uuid and l.campaign_id=p_campaign;
      else
        select l.id,l.holder_id,l.name,l.is_active,l.claim_mode,l.scan_behavior
          into v_source,v_holder,v_container_name,v_active,v_claim_mode,v_scan_behavior
          from public.loot_sources l where l.id=v_container_id_text::uuid and l.campaign_id=p_campaign for update;
      end if;
      if v_source is null then
        raise exception 'Row %: container_id unavailable in this campaign',v_no using errcode='22023';
      end if;
      if v_container_name_text<>'' and lower(v_container_name_text)<>lower(btrim(v_container_name)) then
        raise exception 'Row %: container_name does not match container_id',v_no using errcode='22023';
      end if;
    else
      select count(*),(array_agg(l.id))[1],min(l.name)
        into v_matches,v_source,v_container_name from public.loot_sources l
        where l.campaign_id=p_campaign and lower(btrim(l.name))=lower(v_container_name_text);
      if v_matches>1 then
        raise exception 'Row %: container name is ambiguous; supply container_id',v_no using errcode='22023';
      end if;
      if v_matches=0 then v_container_name:=v_container_name_text;
      else
        if p_dry_run then
          select l.holder_id,l.is_active,l.claim_mode,l.scan_behavior
            into v_holder,v_active,v_claim_mode,v_scan_behavior
            from public.loot_sources l where l.id=v_source and l.campaign_id=p_campaign;
        else
          select l.holder_id,l.is_active,l.claim_mode,l.scan_behavior
            into v_holder,v_active,v_claim_mode,v_scan_behavior
            from public.loot_sources l where l.id=v_source and l.campaign_id=p_campaign for update;
        end if;
      end if;
    end if;
    v_new_source:=v_source is null;
    if not v_new_source then
      if not coalesce(v_active,false) or v_claim_mode<>'first_claim'
        or v_scan_behavior<>'instant'
        or exists(select 1 from public.loot_claims cl where cl.loot_source_id=v_source and cl.status='completed') then
        raise exception 'Row %: container is claimed, inactive, or not a supported QR loot source',
          v_no using errcode='22023';
      end if;
      if exists(select 1 from public.interaction_tokens t where t.loot_source_id=v_source
        and t.action_type='loot' and t.revoked_at is null
        and (t.expires_at is null or t.expires_at>now())
        and (t.max_uses is null or t.use_count<t.max_uses)) then
        raise exception 'Row %: container already has an active QR token; use a new container',
          v_no using errcode='22023';
      end if;
    end if;
    v_source_key:=case when v_new_source then 'new:'||lower(v_container_name) else 'id:'||v_source::text end;
    if v_new_source and not v_source_key=any(v_new_keys) then
      v_new_keys:=array_append(v_new_keys,v_source_key);
      v_new_count:=v_new_count+1;
      if v_new_count>50 then
        raise exception 'Too many new containers in one import (max 50)' using errcode='22023';
      end if;
    end if;
    v_item_id:=null;v_item_name:=null;v_currency_id:=null;v_currency_precision:=null;
    v_amount:=null;v_quantity:=null;v_old_qty:=null;v_old_amount:=null;
    if v_kind='item' then
      if v_item_id_text='' and v_item_name_text='' then
        raise exception 'Row %: item_name or item_definition_id required',v_no using errcode='22023';
      end if;
      if v_currency_code<>'' or v_amount_text<>'' then
        raise exception 'Row %: item rows must leave currency fields blank',v_no using errcode='22023';
      end if;
      if v_qty_text !~ '^[0-9]{1,3}$' then
        raise exception 'Row %: quantity must be an integer between 1 and 500',v_no using errcode='22023';
      end if;
      v_quantity:=v_qty_text::integer;
      if v_quantity not between 1 and 500 then
        raise exception 'Row %: item quantity must be 1–500',v_no using errcode='22023';
      end if;
      v_total_units:=v_total_units+v_quantity;
      if v_total_units>10000 then
        raise exception 'Loot CSV exceeds 10,000 total item units' using errcode='22023';
      end if;
      if v_item_id_text<>'' then
        if v_item_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          raise exception 'Row %: invalid item_definition_id UUID',v_no using errcode='22023';
        end if;
        v_item_id:=v_item_id_text::uuid;
        select d.name into v_item_name from public.item_definitions d
          where d.id=v_item_id and (d.campaign_id=p_campaign
            or (d.campaign_id is null and d.ruleset_version_id=v_ruleset));
        if not found then raise exception 'Row %: item not available in campaign',v_no using errcode='22023';end if;
        if v_item_name_text<>'' and lower(v_item_name_text)<>lower(btrim(v_item_name)) then
          raise exception 'Row %: item_name does not match item_definition_id',v_no using errcode='22023';
        end if;
      else
        select count(*),(array_agg(d.id))[1],min(d.name) into v_matches,v_item_id,v_item_name
          from public.item_definitions d
          where lower(btrim(d.name))=lower(v_item_name_text)
          and (d.campaign_id=p_campaign or (d.campaign_id is null and d.ruleset_version_id=v_ruleset));
        if v_matches<>1 then
          raise exception 'Row %: item name missing or ambiguous: %',v_no,v_item_name_text using errcode='22023';
        end if;
      end if;
      v_entry_key:=v_source_key||'|item:'||v_item_id::text;
      if v_entry_key=any(v_seen) then
        raise exception 'Row %: duplicate container/item pair; combine quantities into one row',v_no using errcode='22023';
      end if;
      v_seen:=array_append(v_seen,v_entry_key);
      if v_new_source then v_old_qty:=0;
      else
        select coalesce(sum(i.quantity),0) into v_old_qty
          from public.item_instances i where i.holder_id=v_holder and i.definition_id=v_item_id;
      end if;
      v_item_rows:=v_item_rows+1;
    else
      if v_item_id_text<>'' or v_item_name_text<>'' or v_qty_text<>'' then
        raise exception 'Row %: currency rows must leave item fields and quantity blank',v_no using errcode='22023';
      end if;
      if v_currency_code='' then
        raise exception 'Row %: currency_code is required',v_no using errcode='22023';
      end if;
      if v_amount_text !~ '^[0-9]{1,10}(\.[0-9]{1,6})?$' then
        raise exception 'Row %: currency_amount must be a positive decimal',v_no using errcode='22023';
      end if;
      v_amount:=v_amount_text::numeric;
      if v_amount<=0 or v_amount>1000000000 then
        raise exception 'Row %: currency_amount must be greater than zero and at most 1,000,000,000',
          v_no using errcode='22023';
      end if;
      select count(*),(array_agg(c.id))[1],max(c.precision_digits)
        into v_matches,v_currency_id,v_currency_precision from public.currencies c
        where c.campaign_id=p_campaign and upper(btrim(c.code))=v_currency_code;
      if v_matches<>1 or v_currency_precision not between 0 and 6 then
        raise exception 'Row %: invalid or ambiguous campaign currency: %',v_no,v_currency_code using errcode='22023';
      end if;
      if round(v_amount,v_currency_precision)<>v_amount then
        raise exception 'Row %: currency % supports only % decimal places',
          v_no,v_currency_code,v_currency_precision using errcode='22023';
      end if;
      v_entry_key:=v_source_key||'|currency:'||v_currency_id::text;
      if v_entry_key=any(v_seen) then
        raise exception 'Row %: duplicate container/currency denomination',v_no using errcode='22023';
      end if;
      v_seen:=array_append(v_seen,v_entry_key);
      if not v_new_source then
        select q.amount into v_old_amount from public.qr_loot_currency q
          where q.source_id=v_source and q.currency_id=v_currency_id;
      end if;
      v_currency_rows:=v_currency_rows+1;
    end if;
    v_plan:=v_plan||jsonb_build_array(jsonb_build_object(
      'row',v_no,'container_name',v_container_name,'container_id',v_source,
      'new_container',v_new_source,'source_key',v_source_key,
      'entry_type',v_kind,'item_name',v_item_name,'item_definition_id',v_item_id,
      'quantity',v_quantity,'old_quantity',v_old_qty,
      'new_quantity',case when v_kind='item' then v_old_qty+v_quantity else null end,
      'currency_code',nullif(v_currency_code,''),'currency_id',v_currency_id,
      'currency_amount',v_amount,'old_currency_amount',v_old_amount,
      'action',case when v_kind='item' then 'add_item' else 'set_currency' end));
  end loop;
  if not p_dry_run then
    if p_expected is null or jsonb_typeof(p_expected)<>'array' or p_expected<>v_plan then
      raise exception 'Loot contents changed since preview or preview missing. Validate & Preview again'
        using errcode='40001';
    end if;
    for v_record in select value from jsonb_array_elements(v_plan) loop
      if (v_record->>'new_container')::boolean then
        v_position:=array_position(v_new_keys,v_record->>'source_key');
        if v_position is null then
          raise exception 'New loot container mapping missing' using errcode='22023';
        end if;
        if coalesce(array_length(v_new_ids,1),0)<v_position then
          v_target_source:=public.create_qr_loot_container(p_campaign,v_record->>'container_name');
          v_new_ids:=array_append(v_new_ids,v_target_source);
          v_created:=v_created+1;
        else v_target_source:=v_new_ids[v_position];
        end if;
      else
        v_target_source:=(v_record->>'container_id')::uuid;
      end if;
      if v_record->>'entry_type'='item' then
        v_result_id:=public.add_qr_loot_item(v_target_source,
          (v_record->>'item_definition_id')::uuid,(v_record->>'quantity')::integer);
      else
        perform public.set_qr_loot_currency(v_target_source,
          (v_record->>'currency_id')::uuid,(v_record->>'currency_amount')::numeric);
      end if;
      v_applied:=v_applied||jsonb_build_array(jsonb_build_object(
        'row',v_record->'row','container_id',v_target_source,
        'entry_type',v_record->'entry_type'));
    end loop;
  end if;
  return jsonb_build_object('mode',case when p_dry_run then 'preview' else 'imported' end,
    'row_count',v_no,'rows',v_plan,'total_units',v_total_units,
    'new_containers',case when p_dry_run then v_new_count else v_created end,
    'item_rows',v_item_rows,'currency_rows',v_currency_rows,
    'applied',v_applied,'item_mode','add','currency_mode','set',
    'new_container_ids',to_jsonb(v_new_ids));
end
$function$;
revoke all on function public.gm_import_qr_loot_csv(uuid,jsonb,boolean,jsonb) from public,anon;
grant execute on function public.gm_import_qr_loot_csv(uuid,jsonb,boolean,jsonb) to authenticated;
